function norm(s) {
  return (s || '').normalize('NFKD').replace(/[̀-ͯ]/g, '')
    .replace(/[^A-Za-z0-9 ]/g, ' ').replace(/\s+/g, ' ').trim().toUpperCase();
}
// Resolve a feed stop name to its SAIS locality (city) by longest prefix match.
export function saisLocality(stopName) {
  const n = norm(stopName);
  for (const loc of SAIS_LOCALITIES) if (n === loc || n.startsWith(loc + ' ')) return loc;
  return null;
}
// Exact OD fare for a SAIS Trasporti leg, or null if the city pair isn't priced.
export function saisOdFare(fromName, toName) {
  const a = saisLocality(fromName), b = saisLocality(toName);
  if (!a || !b || a === b) return null;
  const c = SAIS_OD[a + '|' + b];
  return typeof c === 'number' ? c : null;
}
